ALTER TABLE public.edges DROP CONSTRAINT edges_origin;
ALTER TABLE public.edges ADD CONSTRAINT edges_origin CHECK(source IN('stated','drawn','decomposed','capability_reference','resolved','co_occurrence','inferred','contradiction'));
CREATE TABLE public.model_routes(object_id uuid PRIMARY KEY REFERENCES public.objects(id),route_key text NOT NULL UNIQUE,attestation_expiry timestamptz,cleared_tiers text[] NOT NULL DEFAULT '{}',eval_status text NOT NULL DEFAULT 'unverified',permitted_task_classes text[] NOT NULL DEFAULT '{}',model_version_pin text,invocation_logging_off boolean NOT NULL DEFAULT false,source_version integer NOT NULL,refreshed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.model_routes TO authenticated;
GRANT ALL ON public.model_routes TO service_role;
ALTER TABLE public.model_routes ENABLE ROW LEVEL SECURITY;
CREATE POLICY model_route_source_visibility ON public.model_routes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.objects o WHERE o.id=model_routes.object_id AND NOT o.is_tombstone AND public.can_read_object(o.permission,o.data_classification)));
CREATE INDEX model_routes_eligibility ON public.model_routes(route_key,attestation_expiry,eval_status);
CREATE OR REPLACE FUNCTION public.project_model_route() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.type='ModelRoute' THEN INSERT INTO public.model_routes(object_id,route_key,attestation_expiry,cleared_tiers,eval_status,permitted_task_classes,model_version_pin,invocation_logging_off,source_version) VALUES(NEW.id,coalesce(NEW.body->>'route_key',NEW.human_ref),CASE WHEN NEW.is_tombstone THEN NULL ELSE (NEW.body->>'attestation_expiry')::timestamptz END,ARRAY(SELECT jsonb_array_elements_text(coalesce(NEW.body->'cleared_content_tiers','[]'))),CASE WHEN NEW.is_tombstone OR NEW.body->'provenance'->>'simulated'='true' THEN 'unverified' ELSE coalesce(NEW.body->>'eval_status','unverified') END,ARRAY(SELECT jsonb_array_elements_text(coalesce(NEW.body->'permitted_task_classes','[]'))),NEW.body->>'model_version_pin',coalesce(NEW.body->>'invocation_logging_off','false')='true',NEW.version) ON CONFLICT(object_id) DO UPDATE SET route_key=excluded.route_key,attestation_expiry=excluded.attestation_expiry,cleared_tiers=excluded.cleared_tiers,eval_status=excluded.eval_status,permitted_task_classes=excluded.permitted_task_classes,model_version_pin=excluded.model_version_pin,invocation_logging_off=excluded.invocation_logging_off,source_version=excluded.source_version,refreshed_at=now(); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.project_model_route() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.project_model_route() TO service_role;
CREATE TRIGGER d_model_route_projection AFTER INSERT OR UPDATE ON public.objects FOR EACH ROW EXECUTE FUNCTION public.project_model_route();
INSERT INTO public.model_routes(object_id,route_key,attestation_expiry,cleared_tiers,eval_status,permitted_task_classes,model_version_pin,invocation_logging_off,source_version) SELECT id,coalesce(body->>'route_key',human_ref),(body->>'attestation_expiry')::timestamptz,ARRAY(SELECT jsonb_array_elements_text(coalesce(body->'cleared_content_tiers','[]'))),CASE WHEN body->'provenance'->>'simulated'='true' THEN 'unverified' ELSE coalesce(body->>'eval_status','unverified') END,ARRAY(SELECT jsonb_array_elements_text(coalesce(body->'permitted_task_classes','[]'))),body->>'model_version_pin',coalesce(body->>'invocation_logging_off','false')='true',version FROM public.objects WHERE type='ModelRoute' AND NOT is_tombstone;
CREATE OR REPLACE FUNCTION public.thread_assert_model_route(p_route text,p_class text,p_task text,p_model text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.model_routes; BEGIN
 SELECT * INTO r FROM public.model_routes WHERE route_key=p_route;
 IF r.object_id IS NULL OR r.attestation_expiry IS NULL OR r.attestation_expiry<=now() OR r.eval_status<>'passed' OR NOT p_class=ANY(r.cleared_tiers) OR NOT p_task=ANY(r.permitted_task_classes) OR NOT r.invocation_logging_off OR r.model_version_pin IS DISTINCT FROM p_model THEN RAISE EXCEPTION 'MODEL_ROUTE_NOT_CLEARED: current attestation, passing evaluation, pinned model, permitted class/task and logging-off evidence required'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.thread_assert_model_route(text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.thread_assert_model_route(text,text,text,text) TO service_role;
COMMENT ON TABLE public.model_routes IS 'Governed eligibility projection, not runtime execution state. Unverified routes fail closed until real clearance evidence is supplied.';